using System.Collections.Generic; using UnityEngine; using ERO.Data;
namespace ERO.Systems { public sealed class WorldSystem:MonoBehaviour { public readonly List<ZoneData> Zones=new List<ZoneData>(); void Awake(){Seed();} public ZoneData Get(string id){return Zones.Find(x=>x.id==id);} void Seed(){Zones.Add(new ZoneData{id="greenhaven",name="Greenhaven",minLevel=1,maxLevel=10,pointsOfInterest=new[]{"Greenhaven Village","Old Ruins","Root Cavern"}});Zones.Add(new ZoneData{id="everwood",name="Everwood",minLevel=10,maxLevel=20,pointsOfInterest=new[]{"Ancient Grove","Rootbound Sanctuary"}});Zones.Add(new ZoneData{id="elyndor",name="Kingdom of Elyndor",minLevel=20,maxLevel=30,pointsOfInterest=new[]{"Elyndria","Royal Castle","Grand Cathedral"}});Zones.Add(new ZoneData{id="frostfall",name="Frostfall",minLevel=30,maxLevel=40,pointsOfInterest=new[]{"Frosthold","Frozen Cathedral"}});Zones.Add(new ZoneData{id="sunscar",name="Sunscar Desert",minLevel=40,maxLevel=50,pointsOfInterest=new[]{"Solara","Aether Pyramid"}});Zones.Add(new ZoneData{id="sylvaris",name="Sylvaris",minLevel=50,maxLevel=60,pointsOfInterest=new[]{"Lunareth","Spirit Heart"}});Zones.Add(new ZoneData{id="abyssia",name="Abyssia",minLevel=60,maxLevel=70,pointsOfInterest=new[]{"Vhar'Zul","Obsidian Fortress"}});Zones.Add(new ZoneData{id="rift",name="The Rift",minLevel=70,maxLevel=80,pointsOfInterest=new[]{"Riftwatch","Rift Nexus"}});Zones.Add(new ZoneData{id="eternalrift",name="Eternal Rift",minLevel=80,maxLevel=90,pointsOfInterest=new[]{"Eternal Gate","World Boss Arena"}});Zones.Add(new ZoneData{id="endlessabyss",name="Endless Abyss",minLevel=90,maxLevel=100,pointsOfInterest=new[]{"Abyss Tower","Eternal King"}}); } }
}
